    height: 100vh;
}

/* Top bar */
.top-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 12px 20px;
    background: var(--bg-card);
    border-bottom: 1px solid var(--border);
    flex-shrink: 0;
}
.top-bar-left { display: flex; align-items: center; gap: 16px; }
.top-bar-right { display: flex; align-items: center; gap: 10px; }
.mode-toggle {
    display: flex;
    background: var(--bg-dark);
    border-radius: 8px;
    padding: 2px;
    gap: 2px;
}
.mode-btn {
    padding: 6px 14px;
    border-radius: 6px;
    border: none;
    cursor: pointer;
    font-size: 0.8rem;
    font-weight: 600;
    background: transparent;
    color: var(--text-secondary);
    transition: all 0.2s;
    display: flex; align-items: center; gap: 6px;
}
.mode-btn.active { background: var(--accent); color: #000; }
.top-btn {
    padding: 8px 12px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: transparent;
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.85rem;
    transition: all 0.2s;
    display: flex; align-items: center; gap: 6px;
}
.top-btn:hover { border-color: var(--accent-dim); color: var(--accent); }
.top-btn.danger:hover { border-color: rgba(239,68,68,0.3); color: var(--red); }
.status-indicator {
    display: flex; align-items: center; gap: 6px;
    padding: 6px 12px;
    border-radius: 8px;
    font-size: 0.8rem;
    font-weight: 600;
}
.status-dot {
    width: 8px; height: 8px;
    border-radius: 50%;
}
.status-ready .status-dot { background: var(--accent); box-shadow: 0 0 6px var(--accent); }
.status-ready { color: var(--accent); }
.status-working .status-dot { background: var(--yellow); box-shadow: 0 0 6px var(--yellow); animation: pulse 1s infinite; }
.status-working { color: var(--yellow); }
.status-error .status-dot { background: var(--red); }
.status-error { color: var(--red); }
@keyframes pulse { 50% { opacity: 0.5; } }

/* Content area */
.content-area {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    padding: 0 20px;
}

/* Quick commands */
.commands-section {
    flex-shrink: 0;
    padding: 12px 0;
    border-bottom: 1px solid var(--border);
}
.commands-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    cursor: pointer;
    padding: 4px 0;
    user-select: none;
}
.commands-header:hover { color: var(--accent); }
.commands-grid {
    display: none;
    margin-top: 10px;
}
.commands-grid.expanded { display: block; }
.cmd-category {
    margin-bottom: 10px;
}
.cmd-category-label {
    font-size: 0.7rem;
    color: var(--text-secondary);
    text-transform: uppercase;
    letter-spacing: 1px;
    margin-bottom: 6px;
    padding-left: 2px;
}
.cmd-row {
    display: flex;
    gap: 8px;
    flex-wrap: wrap;
}
.cmd-btn {
    padding: 6px 14px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: var(--bg-card);
    color: var(--text-primary);
    cursor: pointer;
    font-size: 0.8rem;
    transition: all 0.2s;
    display: flex; align-items: center; gap: 6px;
    position: relative;
}
.cmd-btn:hover {
    border-color: var(--accent-dim);
    background: var(--bg-card-hover);
}
.cmd-btn .cmd-actions {
    display: none;
    position: absolute;
    right: -4px;
    top: -4px;
    gap: 2px;
}
.cmd-btn:hover .cmd-actions { display: flex; }
.cmd-action {
    width: 18px; height: 18px;
    border-radius: 4px;
    border: none;
    background: var(--bg-dark);
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.6rem;
    display: flex; align-items: center; justify-content: center;
}
.cmd-action:hover { color: var(--accent); }
.cmd-action.delete:hover { color: var(--red); }
.cmd-add {
    padding: 6px 12px;
    border-radius: 8px;
    border: 1px dashed var(--border);
    background: transparent;
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.8rem;
}
.cmd-add:hover { border-color: var(--accent); color: var(--accent); }

/* Scheduled tasks section */
.scheduled-section {
    flex-shrink: 0;
    max-height: 120px;
    overflow-y: auto;
    border-bottom: 1px solid var(--border);
    padding: 8px 0;
    display: none;
}
.scheduled-section.has-tasks { display: block; }
.sched-item {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 8px;
    border-radius: 6px;
    font-size: 0.8rem;
    margin-bottom: 4px;
}
.sched-item:hover { background: var(--bg-card); }
.sched-left { display: flex; align-items: center; gap: 8px; }
.sched-right { display: flex; align-items: center; gap: 4px; }
.sched-badge {
    padding: 2px 6px;
    border-radius: 4px;
    font-size: 0.65rem;
    font-weight: 600;
}
.sched-badge.once { background: var(--blue-dim); color: var(--blue); }
.sched-badge.recurring { background: var(--accent-dim); color: var(--accent); }
.sched-badge.paused { background: rgba(107,114,128,0.2); color: #6b7280; }
.sched-btn {
    width: 24px; height: 24px;
    border-radius: 4px;
    border: none;
    background: transparent;
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.7rem;
    display: flex; align-items: center; justify-content: center;
}

