        }

        /* Responsive */
        @media (max-width: 768px) {
            .top-bar { flex-wrap: wrap; gap: 8px; padding: 10px; }
            .content-area { padding: 0 12px; }
            .msg { max-width: 95%; }
        }

        /* Command preview block */
        .command-block {
            background: var(--bg-card);
            border: 1px solid var(--border);
            border-radius: 10px;
            margin: 10px 16px;
            overflow: hidden;
            animation: slideIn 0.2s ease;
        }
        @keyframes slideIn { from { opacity: 0; transform: translateY(8px); } to { opacity: 1; transform: translateY(0); } }
        .command-block .cmd-header {
            display: flex; align-items: center; gap: 8px;
            padding: 10px 14px; background: rgba(0,0,0,0.3);
            border-bottom: 1px solid var(--border); font-weight: 600; font-size: 0.85rem;
        }
        .command-block .cmd-header .badge {
            margin-left: auto; padding: 2px 10px; border-radius: 4px; font-size: 0.7rem; font-weight: 700;
        }
        .command-block .badge.manual { background: #f59e0b; color: #000; }
        .command-block .badge.auto { background: var(--accent); color: #000; }
        .command-block .cmd-preview {
            margin: 0; padding: 14px; background: rgba(0,0,0,0.2); color: var(--accent);
            font-family: 'JetBrains Mono','Fira Code',monospace; font-size: 0.82rem;
            white-space: pre-wrap; word-break: break-all; max-height: 250px; overflow-y: auto;
        }
        .command-block .cmd-editor {
            width: 100%; padding: 14px; background: rgba(0,0,0,0.2); color: var(--accent);
            border: none; border-top: 1px dashed var(--border);
            font-family: 'JetBrains Mono','Fira Code',monospace; font-size: 0.82rem;
            resize: vertical; min-height: 80px; display: none;
        }
        .command-block .cmd-editor:focus { outline: none; background: rgba(0,0,0,0.3); }
        .command-block .cmd-editor.modified { border-color: #f59e0b; box-shadow: inset 0 0 0 1px rgba(245,158,11,0.3); }
        .command-block.editing .cmd-preview { display: none; }
        .command-block.editing .cmd-editor { display: block; }
        .command-block .cmd-actions {
            display: flex; justify-content: space-between; align-items: center;
            padding: 10px 14px; background: rgba(0,0,0,0.3); border-top: 1px solid var(--border);
        }
        .command-block .cmd-actions .act-group { display: flex; gap: 8px; }
        .command-block .act-btn {
            padding: 7px 16px; border-radius: 6px; border: none; cursor: pointer;
            font-size: 0.8rem; font-weight: 600; display: flex; align-items: center; gap: 6px;
            transition: all 0.2s;
        }
        .act-btn.primary { background: var(--accent); color: #000; }
        .act-btn.primary:hover { filter: brightness(1.1); }
        .act-btn.secondary { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }
        .act-btn.secondary:hover { border-color: var(--accent-dim); color: var(--text-primary); }
        .act-btn.warn { background: rgba(245,158,11,0.2); border: 1px solid #f59e0b; color: #f59e0b; }

        /* Risk indicator */
        .risk-indicator { display: flex; align-items: center; gap: 8px; padding: 8px 14px; font-size: 0.8rem; }
        .risk-dot { width: 8px; height: 8px; border-radius: 50%; }
        .risk-dot.low { background: var(--accent); }
        .risk-dot.medium { background: #fbbf24; }
        .risk-dot.high { background: #f97316; }
        .risk-dot.critical { background: var(--red); }

        /* Code result block */
        .result-block {
            background: var(--bg-card); border: 1px solid var(--border);
            border-left: 3px solid var(--accent); border-radius: 10px;
            margin: 10px 16px; overflow: hidden;
        }
        .result-block .res-header {
            display: flex; align-items: center; gap: 8px;
            padding: 10px 14px; background: rgba(0,0,0,0.3);
            border-bottom: 1px solid var(--border); font-weight: 600; font-size: 0.85rem;
        }
        .result-block .res-content {
            margin: 0; padding: 14px; background: rgba(0,0,0,0.2); color: var(--text-primary);
            font-family: 'JetBrains Mono','Fira Code',monospace; font-size: 0.82rem;
            white-space: pre-wrap; max-height: 300px; overflow-y: auto;
        }
        .result-block .res-actions {
            display: flex; justify-content: space-between; align-items: center;
            padding: 10px 14px; background: rgba(0,0,0,0.3); border-top: 1px solid var(--border);
        }

        /* Auto-send countdown */
        .auto-countdown {
            display: flex; align-items: center; gap: 6px;
            color: var(--accent); font-size: 0.8rem; font-weight: 600;
        }

        /* Security settings modal tabs */
        .sec-tabs { display: flex; gap: 4px; margin-bottom: 16px; flex-wrap: wrap; }
        .sec-tabs .tab-btn {
            padding: 8px 14px; border-radius: 8px; border: 1px solid var(--border);
            background: transparent; color: var(--text-secondary); cursor: pointer;
            font-size: 0.78rem; font-weight: 600; transition: all 0.2s;
            display: flex; align-items: center; gap: 6px;
        }
        .sec-tabs .tab-btn.active { background: var(--accent); color: #000; border-color: var(--accent); }
        .sec-tab-content { display: none; }
        .sec-tab-content.active { display: block; }
        .sec-section { margin-bottom: 16px; padding-bottom: 12px; border-bottom: 1px solid var(--border); }
        .sec-section:last-child { border-bottom: none; }
        .sec-section h4 { font-size: 0.85rem; margin-bottom: 10px; display: flex; align-items: center; gap: 8px; }
        .sec-item {
            display: flex; align-items: flex-start; gap: 10px;
            padding: 10px 12px; margin: 6px 0; background: var(--bg-dark);
            border-radius: 8px; cursor: pointer; transition: background 0.2s;
        }
        .sec-item:hover { background: rgba(255,255,255,0.05); }
        .sec-item input[type="checkbox"] { margin-top: 3px; flex-shrink: 0; }
        .sec-item .sec-text { flex: 1; }
        .sec-item .sec-text span { font-weight: 500; font-size: 0.85rem; display: block; }
        .sec-item .sec-text small { color: var(--text-secondary); font-size: 0.75rem; display: block; margin-top: 2px; }
        .sec-item.danger { border-left: 3px solid var(--red); }
        .sec-item.critical { border-left: 3px solid #f97316; }
        .sec-item.disabled { opacity: 0.6; }
        .sec-input { margin: 10px 0; }
        .sec-input label { display: block; font-size: 0.82rem; font-weight: 500; margin-bottom: 6px; }
        .sec-input input[type="number"] {
            padding: 8px 12px; border-radius: 6px; border: 1px solid var(--border);
            background: var(--bg-dark); color: var(--text-primary); width: 100px; font-size: 0.85rem;
        }
        .sec-input small { display: block; margin-top: 4px; color: var(--text-secondary); font-size: 0.72rem; }

        /* Command history mini */
        .cmd-history { margin-top: 8px; }
        .cmd-history .hist-item {
            display: flex; justify-content: space-between; align-items: center;
            padding: 6px 10px; margin: 3px 0; background: var(--bg-dark); border-radius: 6px;
            font-size: 0.75rem; cursor: pointer; transition: background 0.2s;
        }
        .cmd-history .hist-item:hover { background: rgba(255,255,255,0.05); }
        .cmd-history .hist-time { color: var(--text-secondary); font-size: 0.7rem; }
    </style>
</head>
