<!-- AUTH SCREEN -->
<div class="auth-overlay" id="authScreen">
    <div class="auth-box">
        <div style="font-size: 2.5rem; margin-bottom: 16px;"><i class="fa-solid fa-shield-halved accent"></i></div>
