                    </button>
                    <button class="act-btn secondary" onclick="skipSendToChat()">
                        <i class="fa-solid fa-forward"></i> <span data-i18n="skip">Skip</span>
                    </button>
                </div>
            </div>
        </div>

        <!-- STATUS BAR -->
        <div class="status-bar" id="statusBar">
            <button class="status-btn" id="statusBtn" onclick="toggleProcess()" title="Stop">
                <i class="fa-solid fa-brain"></i>
            </button>
            <span class="status-timer" id="workingTimer"></span>
            <div class="status-divider"></div>
            <span class="status-action" id="statusAction">Claude thinking...</span>
        </div>

        <!-- INPUT AREA -->
        <div class="input-area">
            <div class="input-wrapper">
                <button class="chat-mode-btn" id="chatModeBtn" onclick="toggleChatMode()" title="Chat mode (dialog only)">
                    <i class="fa-solid fa-comment-dots"></i>
                </button>
                <textarea class="input-field" id="chatInput"
