.sched-btn:hover { background: var(--bg-card-hover); color: var(--accent); }
.sched-btn.danger:hover { color: var(--red); }

/* Chat area */
.chat-area {
    flex: 1;
    overflow-y: auto;
    padding: 16px 0;
    display: flex;
    flex-direction: column;
    gap: 12px;
}
.chat-area::-webkit-scrollbar { width: 6px; }
.chat-area::-webkit-scrollbar-track { background: transparent; }
.chat-area::-webkit-scrollbar-thumb { background: var(--border); border-radius: 3px; }

.msg {
    max-width: 85%;
    padding: 12px 16px;
    border-radius: 12px;
    font-size: 0.9rem;
    line-height: 1.6;
    word-wrap: break-word;
    position: relative;
}
.msg-user {
    align-self: flex-end;
    background: var(--blue);
    color: #fff;
    border-bottom-right-radius: 4px;
}
.msg-assistant {
    align-self: flex-start;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-bottom-left-radius: 4px;
}
.msg-code-result {
    align-self: flex-start;
    background: rgba(0,0,0,0.4);
    border: 1px solid rgba(0,255,136,0.2);
    border-left: 3px solid var(--accent);
    border-bottom-left-radius: 4px;
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.8rem;
}
.msg-time {
    font-size: 0.65rem;
    color: rgba(255,255,255,0.5);
    margin-top: 6px;
}
.msg-assistant .msg-time { color: var(--text-secondary); }

/* Code blocks */
.msg pre {
    background: rgba(0,0,0,0.4);
    border-radius: 8px;
    padding: 12px;
    margin: 8px 0;
    overflow-x: auto;
    position: relative;
}
.msg code {
    font-family: 'JetBrains Mono', 'Fira Code', monospace;
    font-size: 0.82rem;
}
.copy-btn {
    position: absolute;
    top: 6px;
    right: 6px;
    padding: 4px 8px;
    border-radius: 4px;
    border: none;
    background: rgba(255,255,255,0.1);
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.7rem;
}
.copy-btn:hover { background: rgba(255,255,255,0.2); color: var(--accent); }

/* Command action buttons (Manual mode) */
.msg-actions {
    display: flex;
    gap: 8px;
    margin-top: 10px;
}
.msg-action-btn {
    padding: 6px 14px;
    border-radius: 8px;
    border: none;
    font-size: 0.8rem;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    display: flex; align-items: center; gap: 6px;
}
.msg-action-btn.send { background: var(--accent); color: #000; }
.msg-action-btn.send:hover { filter: brightness(1.1); }
.msg-action-btn.edit { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }
.msg-action-btn.edit:hover { border-color: var(--accent); color: var(--accent); }
.msg-action-btn.analyze { background: var(--blue); color: #fff; }
.msg-action-btn.skip { background: transparent; border: 1px solid var(--border); color: var(--text-secondary); }

/* Status bar */
.status-bar {
    display: none;
    align-items: center;
    gap: 10px;
    padding: 8px 14px;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 20px;
    font-size: 0.82rem;
    align-self: flex-start;
}
.status-bar.active { display: flex; }
.status-btn {
    width: 34px; height: 34px;
    border-radius: 50%;
    border: 2px solid var(--border);
    background: transparent;
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
    font-size: 0.85rem;
    transition: all 0.2s;
    flex-shrink: 0;
}
.status-btn.thinking { border-color: #fbbf24; color: #fbbf24; }
.status-btn.executing { border-color: #3b82f6; color: #3b82f6; }
.status-btn.done { border-color: #22c55e; color: #22c55e; pointer-events: none; }
.status-btn.stopped { border-color: #ef4444; color: #ef4444; pointer-events: none; }
.status-btn.error { border-color: #ef4444; color: #ef4444; pointer-events: none; }
.status-btn:hover:not(.done):not(.stopped):not(.error) {
    border-color: #ef4444; color: #ef4444; background: rgba(239,68,68,0.1);
}
@keyframes sb-pulse { 0%,100% { opacity:1; } 50% { opacity:0.4; } }
@keyframes sb-spin { to { transform: rotate(360deg); } }
.status-btn.thinking i { animation: sb-pulse 1.5s ease-in-out infinite; }
.status-btn.executing i { animation: sb-spin 1.2s linear infinite; }
.status-divider { width: 1px; height: 18px; background: var(--border); flex-shrink: 0; }
.status-timer { opacity: 0.6; font-size: 0.75rem; white-space: nowrap; }
.status-action { color: var(--text-secondary); white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 220px; }

/* Confirm buttons */
.confirm-buttons { display: flex; gap: 8px; margin-top: 8px; }
.btn-confirm {
    padding: 6px 14px; border-radius: 8px; border: none; cursor: pointer;
    font-size: 0.8rem; font-weight: 600; transition: all 0.2s;
}
.btn-confirm.yes { background: #22c55e; color: #fff; }
.btn-confirm.yes:hover { filter: brightness(1.1); }
.btn-confirm.clarify { background: transparent; border: 1px solid var(--blue); color: var(--blue); }
.btn-confirm.clarify:hover { background: rgba(59,130,246,0.1); }

/* Input area */
.input-area {
    flex-shrink: 0;
    padding: 12px 0 16px;
    border-top: 1px solid var(--border);
}
.input-wrapper {
    display: flex;
    gap: 10px;
    align-items: flex-end;
}
.input-field {
    flex: 1;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: 12px;
    padding: 12px 16px;
    color: var(--text-primary);
    font-size: 0.9rem;
    resize: none;
    outline: none;
    min-height: 44px;
    max-height: 150px;
    font-family: inherit;
    line-height: 1.4;
}
.input-field:focus { border-color: var(--accent-dim); }
.input-field::placeholder { color: var(--text-secondary); }
.send-btn {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    border: none;
    background: var(--accent);
    color: #000;
    cursor: pointer;
    font-size: 1rem;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    flex-shrink: 0;
}
.send-btn:hover { filter: brightness(1.1); box-shadow: 0 0 15px var(--accent-dim); }
.send-btn:disabled { opacity: 0.5; cursor: not-allowed; }

/* Chat mode button */
.chat-mode-btn {
    width: 44px;
    height: 44px;
    border-radius: 12px;
    border: 2px solid var(--border);
    background: transparent;
    color: var(--text-secondary);
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: all 0.2s;
    flex-shrink: 0;
    font-size: 1rem;
}
.chat-mode-btn:hover {
    border-color: var(--blue);
    color: var(--blue);
}
.chat-mode-btn.active {
    border-color: var(--accent);
    background: rgba(0, 255, 136, 0.08);
    color: var(--accent);
}
.chat-mode-btn.active i {
    animation: pulse 2s infinite;
}
@keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
}

/* Modals */
.modal-overlay {
    display: none;
    position: fixed;
    top: 0; left: 0; right: 0; bottom: 0;
    background: rgba(0,0,0,0.8);
    z-index: 1000;
    align-items: center;
    justify-content: center;
    padding: 20px;
}
.modal-overlay.active { display: flex; }
.modal-content {
    background: var(--bg-card);
    border-radius: 16px;
    max-width: 550px;
    width: 100%;
    max-height: 80vh;
    overflow-y: auto;
    border: 1px solid var(--border);
}
.modal-header {
    padding: 16px 20px;
    border-bottom: 1px solid var(--border);
    display: flex;
    justify-content: space-between;
    align-items: center;
    position: sticky;
    top: 0;
    background: var(--bg-card);
    border-radius: 16px 16px 0 0;
}
.modal-body { padding: 20px; }
.modal-footer {
    padding: 16px 20px;
    border-top: 1px solid var(--border);
    display: flex;
    justify-content: flex-end;
    gap: 10px;
}
.modal-close {
    width: 32px; height: 32px;
    border-radius: 8px;
    border: none;
    background: rgba(255,255,255,0.1);
    color: var(--text-secondary);
    cursor: pointer;
    display: flex; align-items: center; justify-content: center;
}
.modal-close:hover { background: rgba(255,255,255,0.2); }

/* Form inputs */
.form-group { margin-bottom: 16px; }
.form-label {
    display: block;
    font-size: 0.8rem;
    color: var(--text-secondary);
    margin-bottom: 6px;
}
.form-input, .form-select, .form-textarea {
    width: 100%;
    padding: 10px 14px;
    border-radius: 8px;
    border: 1px solid var(--border);
    background: var(--bg-dark);
    color: var(--text-primary);
    font-size: 0.9rem;
    outline: none;
}
.form-input:focus, .form-select:focus, .form-textarea:focus { border-color: var(--accent-dim); }
.form-textarea { min-height: 80px; resize: vertical; font-family: inherit; }
.form-select { cursor: pointer; }
.form-select option { background: var(--bg-dark); }
.form-row { display: flex; gap: 10px; align-items: end; }
.form-row > * { flex: 1; }
.form-radio-group { display: flex; flex-direction: column; gap: 8px; }
.form-radio {
    display: flex; align-items: center; gap: 8px;
    font-size: 0.85rem; cursor: pointer;
}
.form-radio input[type="radio"] { accent-color: var(--accent); }

.btn {
    padding: 8px 16px;
    border-radius: 8px;
    font-weight: 600;
    cursor: pointer;
    transition: all 0.2s;
    border: none;
    font-size: 0.85rem;
    display: inline-flex; align-items: center; gap: 6px;
}
.btn-primary { background: var(--accent); color: #000; }
.btn-primary:hover { filter: brightness(1.1); }
.btn-ghost {
    background: transparent;
    border: 1px solid var(--border);
    color: var(--text-secondary);
}
.btn-ghost:hover { border-color: var(--accent-dim); color: var(--accent); }
.btn-danger { background: var(--red); color: #fff; }

/* Knowledge base file list */
.kb-file {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 10px 12px;
    border-radius: 8px;
    border: 1px solid var(--border);
    margin-bottom: 8px;
}
.kb-file:hover { border-color: var(--accent-dim); }
.kb-file-info { display: flex; align-items: center; gap: 10px; }
.kb-file-icon { color: var(--text-secondary); }
.kb-file-name { font-size: 0.85rem; }
.kb-file-size { font-size: 0.7rem; color: var(--text-secondary); }
.kb-badge {
    display: inline-block;
    padding: 1px 6px;
    border-radius: 4px;
    font-size: 0.6rem;
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}
.kb-badge-rules { background: rgba(251,191,36,0.15); color: #fbbf24; }
.kb-badge-context { background: rgba(59,130,246,0.15); color: #3b82f6; }
.kb-badge-strategy { background: rgba(168,85,247,0.15); color: #a855f7; }
.kb-badge-ref { background: rgba(107,114,128,0.15); color: #9ca3af; }
.kb-file-actions { display: flex; gap: 4px; }
.kb-file-actions button {
    width: 28px; height: 28px;
    border-radius: 6px;
    border: none;
    background: transparent;
    color: var(--text-secondary);
    cursor: pointer;
    font-size: 0.75rem;
    display: flex; align-items: center; justify-content: center;
}
.kb-file-actions button:hover { background: var(--bg-card-hover); color: var(--accent); }
.kb-file-actions button.danger:hover { color: var(--red); }

/* Settings checkboxes */
.setting-check {
    display: flex; align-items: center; gap: 10px;
    padding: 8px 0;
    font-size: 0.85rem;
}
.setting-check input[type="checkbox"] {
    accent-color: var(--accent);
    width: 16px; height: 16px;
}

/* Subscription widget */
.sub-widget {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 6px 12px;
    border-radius: 8px;
    border: 1px solid var(--border);
    cursor: pointer;
    transition: all 0.2s;
}
.sub-widget:hover { border-color: rgba(251,191,36,0.3); }

/* Session indicator */
.session-widget {
    display: flex;
    align-items: center;
    gap: 6px;
    padding: 4px 10px;
    border-radius: 6px;
    font-size: 0.7rem;
    color: var(--text-secondary);
    border: 1px solid var(--border);
    cursor: pointer;
    transition: all 0.2s;
}
.session-widget:hover { border-color: var(--accent-dim); color: var(--text-primary); }
.session-widget .session-dot {
    width: 6px; height: 6px;
    border-radius: 50%;
    background: var(--accent);
    animation: pulse-dot 2s infinite;
}
@keyframes pulse-dot { 0%,100% { opacity: 1; } 50% { opacity: 0.4; } }

/* System messages */
.msg-system-info {
    text-align: center;
    padding: 8px 16px;
    font-size: 0.75rem;
    color: var(--text-secondary);
    font-style: italic;
    border-bottom: 1px solid var(--border);
}

/* Usage stats grid */
.usage-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 12px;
    margin-bottom: 16px;
}
.usage-card {
    padding: 14px;
    border-radius: 10px;
    background: var(--bg-dark);
    border: 1px solid var(--border);
}
.usage-card-label { font-size: 0.7rem; color: var(--text-secondary); margin-bottom: 4px; }
.usage-card-value { font-size: 1.2rem; font-weight: 700; }
.usage-card-sub { font-size: 0.7rem; color: var(--text-secondary); margin-top: 2px; }
.usage-bar-wrap {
    height: 6px;
    background: rgba(255,255,255,0.1);
    border-radius: 3px;
    overflow: hidden;
    margin-top: 8px;
}
.usage-bar-fill {
    height: 100%;
    border-radius: 3px;
    transition: width 0.3s;
}
.usage-day-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: 6px 0;
    border-bottom: 1px solid var(--border);
    font-size: 0.8rem;
}
.usage-day-row:last-child { border-bottom: none; }

/* Update button dot */
.update-dot {
    position: absolute;
    top: 4px; right: 4px;
    width: 8px; height: 8px;
    background: var(--accent);
    border-radius: 50%;
    box-shadow: 0 0 6px var(--accent);
    animation: pulse 2s infinite;
}
/* Update modal states */
.update-state { display: none; text-align: center; padding: 20px 0; }
.update-state.active { display: block; }
.update-state .update-icon { font-size: 2rem; margin-bottom: 12px; }
.update-state h4 { font-size: 1rem; font-weight: 600; margin-bottom: 8px; }
.update-state p { font-size: 0.85rem; color: var(--text-secondary); margin-bottom: 12px; }
.update-version-badge {
    display: inline-block;
    padding: 4px 10px;
    border-radius: 6px;
    font-family: monospace;
    font-size: 0.85rem;
    font-weight: 600;
}
.update-version-old { background: rgba(255,255,255,0.1); color: var(--text-secondary); }
.update-version-new { background: rgba(0,255,136,0.15); color: var(--accent); }
.update-arrow { margin: 0 8px; color: var(--text-secondary); }
