input.new_string:
/* Responsive */
@media (max-width: 768px) {
    /* Prevent horizontal scroll */
    body { overflow-x: hidden; }

    /* Top bar */
    .top-bar {
        flex-wrap: wrap;
        gap: 8px;
        padding: 10px;
    }
    .top-bar-left, .top-bar-right {
        gap: 6px;
    }

    /* Hide less important widgets on mobile */
    .session-widget, .sub-widget {
        display: none;
    }

    /* Content area */
    .content-area {
        padding: 0 10px;
    }

    /* Messages */
    .msg {
        max-width: 100%;
        padding: 10px 12px;
        font-size: 0.85rem;
    }

    /* Code blocks - prevent overflow */
    .msg pre {
        overflow-x: auto;
        max-width: 100%;
    }
    .msg code {
        word-break: break-all;
        white-space: pre-wrap;
    }

    /* Command block */
    .command-block {
        margin: 10px 0;
    }
    .cmd-preview, .cmd-editor {
        font-size: 0.75rem;
        word-break: break-word;
        overflow-x: auto;
    }
    .command-block .cmd-actions {
        flex-wrap: wrap;
        gap: 6px;
    }
    .command-block .act-group {
        width: 100%;
        justify-content: flex-end;
    }

    /* Result block */
    .result-block {
        margin: 10px 0;
    }
    .res-content {
        font-size: 0.75rem;
        word-break: break-word;
        overflow-x: auto;
    }
    .result-block .res-actions {
        flex-wrap: wrap;
        gap: 6px;
    }

    /* Quick commands */
    .cmd-row {
        gap: 6px;
    }
    .cmd-btn {
        padding: 5px 10px;
        font-size: 0.75rem;
    }

    /* Status bar */
    .status-bar {
        padding: 6px 10px;
        font-size: 0.75rem;
    }
    .status-action {
        max-width: 120px;
    }

    /* Input area */
    .input-area {
        padding: 10px 0 12px;
    }
    .input-field {
        padding: 10px 12px;
        font-size: 0.85rem;
    }
    .send-btn, .chat-mode-btn {
        width: 40px;
        height: 40px;
    }

    /* Modal */
    .modal-content {
        max-width: 95%;
        max-height: 90vh;
    }
    .modal-body {
        padding: 14px;
    }

    /* Security tabs */
    .sec-tabs {
        overflow-x: auto;
        flex-wrap: nowrap;
    }
    .sec-tabs .tab-btn {
        padding: 6px 10px;
        font-size: 0.7rem;
        white-space: nowrap;
    }
}

